function boolValue(value) {
  return value === true || value === 'true' || value === 1 || value === '1'
}

function color(value, fallback) {
  if (typeof value === 'string' && /^#[0-9a-fA-F]{6}$/.test(value)) {
    return value
  }
  return fallback
}

function themePalette(theme, config) {
  const palettes = {
    dusk: {
      bgStart: '#172033',
      bgEnd: '#315469',
      dial: '#F4EBDD',
      ink: '#16202A',
      muted: '#7C8A92',
      accent: '#C66A4A',
    },
    paper: {
      bgStart: '#E8DDC9',
      bgEnd: '#B9A98E',
      dial: '#FAF4E8',
      ink: '#25211B',
      muted: '#817765',
      accent: '#9A5A32',
    },
    maritime: {
      bgStart: '#0F2B35',
      bgEnd: '#2F6F73',
      dial: '#EEF3EA',
      ink: '#10242B',
      muted: '#6D8790',
      accent: '#D08B55',
    },
    monochrome: {
      bgStart: '#111827',
      bgEnd: '#374151',
      dial: '#F3F4F6',
      ink: '#111827',
      muted: '#6B7280',
      accent: '#D1D5DB',
    },
    midnight: {
      bgStart: '#020617',
      bgEnd: '#0B1120',
      dial: '#050505',
      ink: '#F8FAFC',
      muted: '#94A3B8',
      accent: '#38BDF8',
    },
    tron: {
      bgStart: '#020617',
      bgEnd: '#071826',
      dial: '#030712',
      ink: '#E0F2FE',
      muted: '#0EA5E9',
      accent: '#22D3EE',
    },
    cyberpunk: {
      bgStart: '#18001F',
      bgEnd: '#2D0638',
      dial: '#07040A',
      ink: '#FDF4FF',
      muted: '#C084FC',
      accent: '#F472B6',
    },
    blacklight: {
      bgStart: '#090014',
      bgEnd: '#1E1B4B',
      dial: '#05030D',
      ink: '#F5F3FF',
      muted: '#A78BFA',
      accent: '#C4B5FD',
    },
    lava: {
      bgStart: '#1C0702',
      bgEnd: '#3B1006',
      dial: '#080402',
      ink: '#FFF7ED',
      muted: '#FB923C',
      accent: '#F97316',
    },
    aurora: {
      bgStart: '#031B1A',
      bgEnd: '#172554',
      dial: '#031313',
      ink: '#ECFEFF',
      muted: '#5EEAD4',
      accent: '#A3E635',
    },
  }

  if (theme === 'custom') {
    return {
      bgStart: color(config.backgroundStart, '#172033'),
      bgEnd: color(config.backgroundEnd, '#315469'),
      dial: color(config.dialColor, '#F4EBDD'),
      ink: color(config.inkColor, '#16202A'),
      muted: color(config.mutedColor, '#7C8A92'),
      accent: color(config.accentColor, '#C66A4A'),
    }
  }

  return palettes[theme] || palettes.dusk
}

function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value))
}

// Every coordinate and size is drawn rounded to two decimals.
function round2(value) {
  return Number(value.toFixed(2))
}

function polar(cx, cy, radius, degrees) {
  const radians = (degrees - 90) * Math.PI / 180
  return {
    x: cx + Math.cos(radians) * radius,
    y: cy + Math.sin(radians) * radius,
  }
}

function handPolygon(cx, cy, length, tail, angle, halfWidth) {
  const tip = polar(cx, cy, length, angle)
  const back = polar(cx, cy, tail, angle + 180)
  const left = polar(cx, cy, halfWidth, angle - 90)
  const right = polar(cx, cy, halfWidth, angle + 90)
  return [tip, left, back, right].map((point) => point.x.toFixed(2) + ',' + point.y.toFixed(2)).join(' ')
}

function fitLabel(value, maxChars) {
  const text = String(value || '').trim()
  if (text.length <= maxChars) {
    return text
  }
  return text.substring(0, Math.max(1, maxChars - 1)).trim() + '…'
}

// The widest a character gets, in ems, in the faces a title is drawn in
// (PT Sans Bold, or Ubuntu on a device that has only that face). A line
// measured with these is never wider on the frame than estimated.
function glyphWidth(char) {
  if (" .,:;'!|ijlI".includes(char)) return 0.33
  if ('()[]{}-/\\"`frt?*_'.includes(char)) return 0.51
  if ('mwMOQ&'.includes(char)) return 0.9
  if ('W%@…'.includes(char)) return 1.06
  if (/[a-z0-9$+<=>^~]/.test(char)) return 0.61
  if (/[A-Z#]/.test(char)) return 0.76
  // Accented letters, other scripts and symbols: a full em.
  return 1
}

function estimateWidth(text, size) {
  let ems = 0
  for (const char of text) {
    ems += glyphWidth(char)
  }
  return ems * size
}

// Shortens text with an ellipsis until it is at most maxWidth wide.
function ellipsize(text, maxWidth, size) {
  if (estimateWidth(text, size) <= maxWidth) {
    return text
  }
  const chars = Array.from(text)
  let count = chars.length - 1
  while (count > 1 && estimateWidth(chars.slice(0, count).join('').trim() + '…', size) > maxWidth) {
    count -= 1
  }
  return chars.slice(0, count).join('').trim() + '…'
}

// Breaks text at spaces into at most maxLines lines no wider than maxWidth.
// The last line takes whatever is left and ends in an ellipsis when that does
// not fit; so does a single word too long for a line.
function wrapLines(text, maxWidth, size, maxLines) {
  if (estimateWidth(text, size) <= maxWidth) {
    return [text]
  }
  const lines = []
  let line = ''
  for (const word of text.split(/\s+/)) {
    const candidate = line ? line + ' ' + word : word
    if (line && estimateWidth(candidate, size) > maxWidth) {
      lines.push(line)
      line = word
    } else {
      line = candidate
    }
  }
  lines.push(line)
  if (lines.length > maxLines) {
    lines.splice(maxLines - 1, lines.length, lines.slice(maxLines - 1).join(' '))
  }
  return lines.map((part) => ellipsize(part, maxWidth, size))
}

function parseTime(value) {
  const match = String(value || '').match(/^(\d{1,2}):(\d{2})(?::(\d{2}))?/)
  if (!match) {
    return null
  }
  return {
    hour: clamp(parseInt(match[1], 10), 0, 23),
    minute: clamp(parseInt(match[2], 10), 0, 59),
    second: clamp(parseInt(match[3] || '0', 10), 0, 59),
  }
}

function arcPath(cx, cy, radius, startDegrees, endDegrees) {
  const start = polar(cx, cy, radius, startDegrees)
  const end = polar(cx, cy, radius, endDegrees)
  const large = Math.abs(endDegrees - startDegrees) > 180 ? 1 : 0
  return 'M ' + start.x.toFixed(2) + ' ' + start.y.toFixed(2) + ' A ' + radius.toFixed(2) + ' ' + radius.toFixed(2) + ' 0 ' + large + ' 1 ' + end.x.toFixed(2) + ' ' + end.y.toFixed(2)
}

function computeLayout(W, H, config, unit) {
  const portrait = H > W
  const minSide = Math.min(W, H)
  const margin = minSide * 0.055
  const outerFactor = 1.08

  if (portrait) {
    const hasPosterText = config.showTitle || config.showDigital
    const textReserve = hasPosterText ? H * 0.26 : 0
    const gap = hasPosterText ? Math.max(unit * 8, H * 0.045) : 0
    const availableHeight = H - margin * 2 - textReserve - gap
    const availableWidth = W - margin * 2.6
    const radius = Math.min(availableWidth / (2 * outerFactor), availableHeight / (2 * outerFactor)) * 0.98
    const safeRadius = Math.max(unit * 18, radius)
    const clockBlockHeight = safeRadius * outerFactor * 2
    const totalHeight = hasPosterText ? clockBlockHeight + gap + textReserve : clockBlockHeight
    const balancedTop = (H - totalHeight) / 2
    const verticalNudge = hasPosterText ? Math.min(gap * 0.45, margin * 1.1) : 0
    const top = Math.max(margin * 1.15, balancedTop + verticalNudge)
    const cy = top + clockBlockHeight / 2

    return {
      portrait: true,
      cx: W / 2,
      cy: cy,
      radius: safeRadius,
      textX: W / 2,
      textY: hasPosterText ? cy + safeRadius * outerFactor + gap + textReserve * 0.36 : H / 2,
      textWidth: W - margin * 2.4,
    }
  }

  const hasPosterText = config.showTitle || config.showDigital
  if (!hasPosterText) {
    const radius = Math.min((W - margin * 2) / (2 * outerFactor), (H - margin * 2) / (2 * outerFactor)) * 0.98
    return {
      portrait: false,
      cx: W / 2,
      cy: H / 2,
      radius: Math.max(unit * 18, radius),
      textX: margin,
      textY: H / 2,
      textWidth: 0,
    }
  }

  const textWidth = clamp(W * 0.25, minSide * 0.26, minSide * 0.42)
  const gutter = minSide * 0.07
  const clockLeft = margin + textWidth + gutter
  const clockRight = W - margin
  const clockWidth = Math.max(minSide * 0.42, clockRight - clockLeft)
  const maxRadiusByWidth = clockWidth / (2 * outerFactor)
  const maxRadiusByHeight = (H - margin * 2) / (2 * outerFactor)
  const radius = Math.min(maxRadiusByWidth, maxRadiusByHeight) * 0.96

  return {
    portrait: false,
    cx: Math.min(clockRight - radius * outerFactor, Math.max(clockLeft + radius * outerFactor, clockLeft + clockWidth / 2)),
    cy: H / 2,
    radius: Math.max(unit * 18, radius),
    textX: margin,
    textY: H * 0.45,
    textWidth: textWidth,
  }
}

function titleFontSize(layout, unit) {
  return clamp(unit * (layout.portrait ? 5.4 : 4.8), 18, 66)
}

// The portrait poster card under the clock: its box, the title broken into
// lines that keep clear of the time icon at the card's left, and where its
// lines go. The background reads the box too, to keep its ribbon off the card.
function portraitCard(layout, config, unit) {
  const width = Math.min(layout.textWidth, unit * 72)
  const baseHeight = unit * (config.showTitle && config.showDigital ? 17 : 12)
  const titleSize = titleFontSize(layout, unit)
  // The icon is centered 7 units in from the card's left and its rays reach
  // 3.3 units out. The title is centered on the card, so it keeps 1.5 units
  // from the icon and as far from the right edge.
  const iconClearance = unit * (7 + 3.3 + 1.5)
  const titleLines = config.showTitle ? wrapLines(config.title, width - iconClearance * 2, titleSize, 2) : []
  // A second title line makes the card one line taller. It grows around
  // textY the way the card sits on it: 42% of the growth upwards.
  const lineStep = titleSize * 1.1
  const extraHeight = titleLines.length > 1 ? lineStep * (titleLines.length - 1) : 0
  const shiftUp = extraHeight * 0.42
  const titleY = layout.textY - titleSize * 0.18 - shiftUp

  return {
    x: layout.textX - width / 2,
    y: layout.textY - baseHeight * 0.42 - shiftUp,
    width: width,
    height: baseHeight + extraHeight,
    titleLines: titleLines,
    titleY: titleY,
    lineStep: lineStep,
    // The digital time goes under the title's last line, or in its place.
    digitalY: config.showTitle ? titleY + extraHeight + titleSize * 1.05 : titleY,
  }
}

// The y of the left end of the background's ribbon line, which rises by 8
// units to its right end.
function ribbonLeftY(H, layout, card, unit) {
  if (!layout.portrait) {
    return H * 0.12
  }
  if (!card) {
    return H * 0.78
  }
  // It would show through the card's glass, so it goes in the band below the
  // card (and its shadow), or between the dial and the card when that band is
  // too narrow, centered in either.
  const rise = unit * 8
  const clearance = unit * 2
  const cardBottom = card.y + card.height + unit * 0.9
  if (H - cardBottom >= rise + clearance * 2) {
    return (cardBottom + H + rise) / 2
  }
  const dialBottom = layout.cy + layout.radius * 1.075
  return (dialBottom + card.y + rise) / 2
}

function PolarLine({ cx, cy, inner, outer, degrees, stroke, width }) {
  const a = polar(cx, cy, inner, degrees)
  const b = polar(cx, cy, outer, degrees)
  return (
    <line
      x1={round2(a.x)}
      y1={round2(a.y)}
      x2={round2(b.x)}
      y2={round2(b.y)}
      stroke={stroke}
      strokeWidth={round2(width)}
      strokeLinecap="round"
    />
  )
}

function RoundedRect({ x, y, width, height, radius, fill, stroke, strokeWidth, opacity }) {
  return (
    <rect
      x={round2(x)}
      y={round2(y)}
      width={round2(width)}
      height={round2(height)}
      rx={round2(radius)}
      ry={round2(radius)}
      fill={fill}
      opacity={opacity}
      stroke={stroke || undefined}
      strokeWidth={stroke ? round2(strokeWidth) : undefined}
    />
  )
}

function NumberText({ text, x, y, size, fill, font, weight }) {
  return (
    <text
      x={round2(x)}
      y={round2(y)}
      fontFamily={font}
      fontSize={round2(size)}
      fontWeight={weight}
      textAnchor="middle"
      dominantBaseline="middle"
      fill={fill}
    >
      {text}
    </text>
  )
}

function Background({ W, H, layout, card, palette, unit, showFlair }) {
  const glowCx = layout.portrait ? W * 0.5 : layout.cx
  const glowCy = layout.portrait ? layout.cy * 0.82 : layout.cy * 0.72
  const glowR = Math.max(W, H) * 0.54
  const cornerCx = layout.portrait ? W * 0.18 : W * 0.08
  const cornerCy = layout.portrait ? H * 0.92 : H * 0.16
  const cornerR = Math.max(W, H) * 0.42
  const ribbonY = ribbonLeftY(H, layout, card, unit)

  return (
    <>
      <defs>
        <linearGradient id="bg" gradientUnits="userSpaceOnUse" x1="0" y1="0" x2={W} y2={H}>
          <stop offset="0" stopColor={palette.bgStart} />
          <stop offset="1" stopColor={palette.bgEnd} />
        </linearGradient>
        <radialGradient id="clockGlow" gradientUnits="userSpaceOnUse" cx={round2(glowCx)} cy={round2(glowCy)} r={round2(glowR)}>
          <stop offset="0" stopColor={palette.accent} stopOpacity="0.34" />
          <stop offset="0.48" stopColor={palette.accent} stopOpacity="0.10" />
          <stop offset="1" stopColor={palette.accent} stopOpacity="0" />
        </radialGradient>
        <radialGradient id="cornerVignette" gradientUnits="userSpaceOnUse" cx={round2(cornerCx)} cy={round2(cornerCy)} r={round2(cornerR)}>
          <stop offset="0" stopColor="#F7F0E6" stopOpacity="0.16" />
          <stop offset="1" stopColor="#F7F0E6" stopOpacity="0" />
        </radialGradient>
      </defs>
      <rect x="0" y="0" width={W} height={H} fill="url(#bg)" />
      {showFlair && (
        <>
          <rect x="0" y="0" width={W} height={H} fill="url(#clockGlow)" />
          <rect x="0" y="0" width={W} height={H} fill="url(#cornerVignette)" />
          <circle cx={round2(W * 0.92)} cy={round2(H * 0.12)} r={round2(unit * 17)} fill="#0B1220" opacity="0.16" />
          <circle cx={round2(W * 0.86)} cy={round2(H * 0.90)} r={round2(unit * 9)} fill="#F7F0E6" opacity="0.08" />
          <line
            x1={round2(W * 0.06)}
            y1={round2(ribbonY)}
            x2={round2(W * 0.94)}
            y2={round2(ribbonY - unit * 8)}
            stroke="#F7F0E6"
            strokeWidth={round2(unit * 0.18)}
            opacity="0.22"
          />
          {Array.from({ length: 7 }, (_, i) => {
            const y = H * (0.18 + i * 0.10)
            return (
              <line
                x1={round2(W * 0.10)}
                y1={round2(y)}
                x2={round2(W * 0.90)}
                y2={round2(y - unit * 5)}
                stroke={palette.accent}
                strokeWidth={round2(unit * 0.10)}
                opacity="0.12"
              />
            )
          })}
        </>
      )}
    </>
  )
}

function Ticks({ cx, cy, radius, style, palette, showMinuteTicks, unit }) {
  const minuteWidth = style === 'minimal' ? unit * 0.2 : unit * 0.28
  const minuteInner = style === 'minimal' ? radius * 0.93 : radius * 0.89
  const hourWidth = style === 'minimal' ? unit * 0.78 : unit * 1.05
  const hourInner = style === 'roman' ? radius * 0.82 : radius * 0.84
  // Every minute but the five-minute ones, where the hour marks go.
  const minutes = showMinuteTicks ? Array.from({ length: 60 }, (_, i) => i).filter((i) => i % 5 !== 0) : []

  return (
    <>
      {minutes.map((minute) => (
        <PolarLine cx={cx} cy={cy} inner={minuteInner} outer={radius * 0.96} degrees={minute * 6} stroke={palette.muted} width={minuteWidth} />
      ))}
      {Array.from({ length: 12 }, (_, hour) => (
        <PolarLine cx={cx} cy={cy} inner={hourInner} outer={radius * 0.96} degrees={hour * 30} stroke={palette.ink} width={hourWidth} />
      ))}
    </>
  )
}

function Numbers({ cx, cy, radius, style, palette, unit }) {
  if (style === 'minimal') {
    return Array.from({ length: 12 }, (_, i) => {
      const p = polar(cx, cy, radius * 0.75, i * 30)
      const r = i === 0 ? unit * 0.95 : unit * 0.58
      return <circle cx={round2(p.x)} cy={round2(p.y)} r={round2(r)} fill={i === 0 ? palette.accent : palette.muted} />
    })
  }

  const roman = ['XII', 'I', 'II', 'III', 'IV', 'V', 'VI', 'VII', 'VIII', 'IX', 'X', 'XI']
  const font = style === 'roman' ? 'CormorantGaramond-Bold.ttf' : 'PTSans-Bold.ttf'
  const size = style === 'roman' ? unit * 5.4 : unit * 4.6
  const labelRadius = style === 'roman' ? radius * 0.68 : radius * 0.69

  return Array.from({ length: 12 }, (_, i) => {
    const p = polar(cx, cy, labelRadius, i * 30)
    const label = style === 'roman' ? roman[i] : String(i === 0 ? 12 : i)
    return <NumberText text={label} x={p.x} y={p.y} size={size} fill={palette.ink} font={font} weight="700" />
  })
}

function Hands({ cx, cy, radius, time, palette, style, showSecondHand, unit }) {
  const hourAngle = ((time.hour % 12) + time.minute / 60 + time.second / 3600) * 30
  const minuteAngle = (time.minute + time.second / 60) * 6
  const secondAngle = time.second * 6

  const minute = polar(cx, cy, radius * 0.73, minuteAngle)
  const tailMinute = polar(cx, cy, radius * 0.12, minuteAngle + 180)
  const second = polar(cx, cy, radius * 0.79, secondAngle)
  const tailSecond = polar(cx, cy, radius * 0.18, secondAngle + 180)
  const cap = style === 'minimal' ? 'round' : 'butt'

  return (
    <>
      <polygon points={handPolygon(cx, cy, radius * 0.46, radius * 0.07, hourAngle, unit * 1.2)} fill={palette.ink} />
      <circle cx={round2(cx)} cy={round2(cy)} r={round2(unit * 1.05)} fill={palette.ink} />
      <line
        x1={round2(tailMinute.x)}
        y1={round2(tailMinute.y)}
        x2={round2(minute.x)}
        y2={round2(minute.y)}
        stroke={palette.ink}
        strokeWidth={round2(unit * 0.95)}
        strokeLinecap={cap}
      />
      {showSecondHand && (
        <line
          x1={round2(tailSecond.x)}
          y1={round2(tailSecond.y)}
          x2={round2(second.x)}
          y2={round2(second.y)}
          stroke={palette.accent}
          strokeWidth={round2(unit * 0.42)}
          strokeLinecap="round"
        />
      )}
      <circle cx={round2(cx)} cy={round2(cy)} r={round2(unit * 2.1)} fill={palette.accent} />
      <circle cx={round2(cx)} cy={round2(cy)} r={round2(unit * 0.72)} fill={palette.dial} />
    </>
  )
}

function TimeIcon({ x, y, size, time, palette }) {
  const isNight = time.hour < 6 || time.hour >= 18
  if (isNight) {
    return (
      <>
        <circle cx={round2(x)} cy={round2(y)} r={round2(size * 0.42)} fill={palette.accent} />
        <circle cx={round2(x + size * 0.18)} cy={round2(y - size * 0.13)} r={round2(size * 0.42)} fill="#0F1724" opacity="0.82" />
        <circle cx={round2(x + size * 0.40)} cy={round2(y - size * 0.32)} r={round2(size * 0.06)} fill="#F7F0E6" opacity="0.72" />
      </>
    )
  }

  return (
    <>
      <circle cx={round2(x)} cy={round2(y)} r={round2(size * 0.34)} fill={palette.accent} />
      {Array.from({ length: 8 }, (_, i) => (
        <PolarLine cx={x} cy={y} inner={size * 0.48} outer={size * 0.66} degrees={i * 45} stroke={palette.accent} width={size * 0.08} />
      ))}
    </>
  )
}

function PosterText({ layout, card, time, palette, config, unit }) {
  if (!config.showTitle && !config.showDigital) {
    return null
  }

  const titleSize = titleFontSize(layout, unit)
  const digitalSize = clamp(unit * (layout.portrait ? 5.0 : 4.2), 16, 56)
  const use24Hour = boolValue(config.use24Hour)
  const hour12 = time.hour % 12 || 12
  const displayHour = use24Hour ? time.hour : hour12
  const suffix = use24Hour ? '' : (time.hour < 12 ? ' AM' : ' PM')
  const digital = (displayHour < 10 ? '0' : '') + displayHour + ':' + (time.minute < 10 ? '0' : '') + time.minute + suffix
  const x = layout.textX

  if (layout.portrait) {
    return (
      <>
        <RoundedRect x={card.x + unit * 0.9} y={card.y + unit * 0.9} width={card.width} height={card.height} radius={unit * 2.8} fill="#0B1220" opacity="0.22" />
        <RoundedRect x={card.x} y={card.y} width={card.width} height={card.height} radius={unit * 2.8} fill="#F7F0E6" stroke="#F7F0E6" strokeWidth={unit * 0.16} opacity="0.10" />
        <TimeIcon x={card.x + unit * 7} y={card.y + card.height / 2} size={unit * 4.7} time={time} palette={palette} />
        {card.titleLines.map((line, i) => (
          <text
            x={round2(x)}
            y={round2(card.titleY + card.lineStep * i)}
            fontFamily="PTSans-Bold.ttf"
            fontSize={round2(titleSize)}
            fontWeight="700"
            textAnchor="middle"
            dominantBaseline="middle"
            fill="#F7F0E6"
          >
            {line}
          </text>
        ))}
        {config.showDigital && (
          <text
            x={round2(x)}
            y={round2(card.digitalY)}
            fontFamily="CascadiaMono.ttf"
            fontSize={round2(digitalSize)}
            textAnchor="middle"
            dominantBaseline="middle"
            fill={palette.accent}
          >
            {digital}
          </text>
        )}
      </>
    )
  }

  const titleMax = Math.floor(layout.textWidth / (titleSize * 0.55))
  const title = fitLabel(config.title, Math.max(6, titleMax))
  const cardWidth = layout.textWidth
  const cardHeight = unit * (config.showTitle && config.showDigital ? 27 : 20)
  const cardY = layout.textY - cardHeight * 0.44
  const textX = x + unit * 4.4
  const titleY = layout.textY
  const digitalY = config.showTitle ? titleY + titleSize * 1.16 : titleY

  return (
    <>
      <RoundedRect x={x + unit * 1.1} y={cardY + unit * 1.1} width={cardWidth} height={cardHeight} radius={unit * 3.1} fill="#0B1220" opacity="0.20" />
      <RoundedRect x={x} y={cardY} width={cardWidth} height={cardHeight} radius={unit * 3.1} fill="#F7F0E6" stroke="#F7F0E6" strokeWidth={unit * 0.16} opacity="0.11" />
      <rect
        x={round2(x)}
        y={round2(cardY)}
        width={round2(unit * 1.15)}
        height={round2(cardHeight)}
        rx={round2(unit * 0.58)}
        ry={round2(unit * 0.58)}
        fill={palette.accent}
      />
      <TimeIcon x={x + cardWidth - unit * 5.2} y={cardY + unit * 5.0} size={unit * 4.0} time={time} palette={palette} />
      {config.showTitle && (
        <text
          x={round2(textX)}
          y={round2(titleY)}
          fontFamily="PTSans-Bold.ttf"
          fontSize={round2(titleSize)}
          fontWeight="700"
          textAnchor="start"
          dominantBaseline="middle"
          fill="#F7F0E6"
        >
          {title}
        </text>
      )}
      {config.showDigital && (
        <text
          x={round2(textX)}
          y={round2(digitalY)}
          fontFamily="CascadiaMono.ttf"
          fontSize={round2(digitalSize)}
          textAnchor="start"
          dominantBaseline="middle"
          fill={palette.accent}
        >
          {digital}
        </text>
      )}
    </>
  )
}

function Placeholder({ W, H, palette, unit }) {
  const size = clamp(unit * 5.2, 16, 54)
  return (
    <>
      <rect x="0" y="0" width={W} height={H} fill={palette.bgStart} />
      <text
        x={round2(W / 2)}
        y={round2(H / 2 - size * 0.4)}
        fontFamily="PTSans-Bold.ttf"
        fontSize={round2(size)}
        fontWeight="700"
        textAnchor="middle"
        dominantBaseline="middle"
        fill="#F7F0E6"
      >
        Clock time is starting…
      </text>
      <text
        x={round2(W / 2)}
        y={round2(H / 2 + size * 0.95)}
        fontFamily="PTSans-Regular.ttf"
        fontSize={round2(size * 0.52)}
        textAnchor="middle"
        dominantBaseline="middle"
        fill={palette.accent}
      >
        The frame will render the dial as soon as the clock value is available.
      </text>
    </>
  )
}

// The bezel, the dial and its rings, under the ticks, numbers and hands.
function Dial({ cx, cy, radius, style, palette, unit }) {
  return (
    <>
      <circle cx={round2(cx + unit * 1.6)} cy={round2(cy + unit * 1.9)} r={round2(radius * 1.06)} fill="#0B1220" opacity="0.28" />
      <circle cx={round2(cx)} cy={round2(cy)} r={round2(radius * 1.075)} fill="#F7F0E6" opacity="0.12" />
      <circle cx={round2(cx)} cy={round2(cy)} r={round2(radius * 1.045)} fill="#0F1724" />
      {/* The roman dial's accent arc is inlaid in the bezel ring (radius to
          1.045 radius), so it is drawn over the bezel, along the ring's middle. */}
      {style === 'roman' && (
        <path
          d={arcPath(cx, cy, radius * 1.0225, 218, 322)}
          fill="none"
          stroke={palette.accent}
          strokeWidth={round2(unit * 0.95)}
          strokeLinecap="round"
        />
      )}
      <circle cx={round2(cx)} cy={round2(cy)} r={round2(radius)} fill={palette.dial} />
      {style === 'station clock' ? (
        <circle cx={round2(cx)} cy={round2(cy)} r={round2(radius * 0.955)} fill="none" stroke={palette.ink} strokeWidth={round2(unit * 0.9)} />
      ) : (
        <circle cx={round2(cx)} cy={round2(cy)} r={round2(radius * 0.94)} fill="none" stroke={palette.muted} strokeWidth={round2(unit * 0.38)} />
      )}
      <circle cx={round2(cx)} cy={round2(cy)} r={round2(radius * 0.79)} fill="none" stroke={palette.muted} strokeWidth={round2(unit * 0.16)} opacity="0.45" />
    </>
  )
}

function Clock({ W, H, unit, time, palette, appConfig }) {
  const style = ['station clock', 'minimal', 'roman'].indexOf(appConfig.style) >= 0 ? appConfig.style : 'station clock'
  const showMinuteTicks = boolValue(appConfig.showMinuteTicks)
  const showSecondHand = boolValue(appConfig.showSecondHand)
  // A blank title (empty, or only spaces) is no title: the card gets no row
  // for it. Without a value at all the app falls back to 'Local time'.
  const title = String(appConfig.title ?? 'Local time').trim()
  const config = {
    title: title,
    showTitle: boolValue(appConfig.showTitle) && title !== '',
    showDigital: boolValue(appConfig.showDigital),
    use24Hour: boolValue(appConfig.use24Hour),
    showBackgroundFlair: boolValue(appConfig.showBackgroundFlair),
  }
  const layout = computeLayout(W, H, config, unit)
  const card = layout.portrait && (config.showTitle || config.showDigital) ? portraitCard(layout, config, unit) : null
  const cx = layout.cx
  const cy = layout.cy
  const radius = layout.radius

  return (
    <>
      <Background W={W} H={H} layout={layout} card={card} palette={palette} unit={unit} showFlair={config.showBackgroundFlair} />
      <PosterText layout={layout} card={card} time={time} palette={palette} config={config} unit={unit} />
      <Dial cx={cx} cy={cy} radius={radius} style={style} palette={palette} unit={unit} />
      <Ticks cx={cx} cy={cy} radius={radius} style={style} palette={palette} showMinuteTicks={showMinuteTicks} unit={unit} />
      <Numbers cx={cx} cy={cy} radius={radius} style={style} palette={palette} unit={unit} />
      <Hands cx={cx} cy={cy} radius={radius} time={time} palette={palette} style={style} showSecondHand={showSecondHand} unit={unit} />
    </>
  )
}

export function get(app, context) {
  const W = context?.imageWidth ?? app.frame.width
  const H = context?.imageHeight ?? app.frame.height
  const unit = Math.min(W, H) / 100
  const time = parseTime(app.config.time)
  const themes = ['dusk', 'midnight', 'tron', 'cyberpunk', 'blacklight', 'lava', 'aurora', 'paper', 'maritime', 'monochrome', 'custom']
  const theme = themes.indexOf(app.config.theme) >= 0 ? app.config.theme : 'dusk'
  const palette = themePalette(theme, app.config)

  return (
    <svg width={W} height={H} viewBox={`0 0 ${W} ${H}`}>
      {time ? (
        <Clock W={W} H={H} unit={unit} time={time} palette={palette} appConfig={app.config} />
      ) : (
        <Placeholder W={W} H={H} palette={palette} unit={unit} />
      )}
    </svg>
  )
}
